


/** Why the buyer is confirming, the email to confirm, and how the code reaches them. */ export type CreateCheckoutCustomerVerificationRequestInput = { /** How the code reaches the buyer. email, the default for save_payment_method and use_saved_payment_methods, emails it. sms texts it: for use_saved_payment_methods, to the mobile phone number saved with the email's details; for confirm_saved_payment_method, to the number given with the payment. Required for confirm_saved_payment_method, and save_payment_method takes only email. */ "channel"?: "email" | "sms"; /** Email the buyer typed, with no surrounding spaces. Customers are matched by email without regard to case. Required for save_payment_method and use_saved_payment_methods, and not allowed for confirm_saved_payment_method. Format: email. maxLength: 255. */ "email"?: string; /** save_payment_method: the buyer asked to save the card they are paying with; Flint emails a code to any valid address. use_saved_payment_methods: the buyer asked to use details they saved at this merchant before. By email, Flint sends a code only when a customer with this email has saved details, an active card saved by email or with a mobile phone number, and the response is the same either way. By sms, Flint texts the number saved with the email's details. confirm_saved_payment_method: after a payment that sent save_payment_method_phone, the buyer confirms the card it saved. */ "purpose": "save_payment_method" | "use_saved_payment_methods" | "confirm_saved_payment_method"; };
